package com.roopesh.jobfinder.service;
import com.roopesh.jobfinder.dto.AuthDtos.*; import com.roopesh.jobfinder.model.User; import com.roopesh.jobfinder.repository.UserRepository; import com.roopesh.jobfinder.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService {private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt; public AuthService(UserRepository users,PasswordEncoder encoder,JwtService jwt){this.users=users;this.encoder=encoder;this.jwt=jwt;}
 public AuthResponse register(RegisterRequest r){if(r.name()==null||r.name().isBlank()||r.email()==null||r.email().isBlank()||r.password()==null||r.password().length()<6)throw new IllegalArgumentException("Name, valid email and password of at least 6 characters are required");if(users.findByEmail(r.email().toLowerCase()).isPresent())throw new IllegalArgumentException("Email already registered");User u=users.save(new User(r.name().trim(),r.email().toLowerCase().trim(),encoder.encode(r.password())));return new AuthResponse(jwt.generate(u.getEmail()),u.getName(),u.getEmail());}
 public AuthResponse login(LoginRequest r){User u=users.findByEmail(r.email().toLowerCase().trim()).orElseThrow(()->new IllegalArgumentException("Invalid email or password"));if(!encoder.matches(r.password(),u.getPassword()))throw new IllegalArgumentException("Invalid email or password");return new AuthResponse(jwt.generate(u.getEmail()),u.getName(),u.getEmail());}
}
